window.kbPageData["views/entry/k-4295561e641ea3cf"] = {"key":"entry/k-4295561e641ea3cf","state":{"route":"entry/k-4295561e641ea3cf"},"node":{"id":"k-4295561e641ea3cf","mode":"k","title":"奇数项等差数列求和","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["奇数项等差数列的和等于中间项乘以项数"],"qs":["国考 2023 地市级 行测#67"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"项数为奇数的等差数列，其各项之和等于中间项乘以项数。","review":{"definition":"项数为奇数的等差数列，其各项之和等于中间项乘以项数。","explanation":"与中间项等距的两项之和等于中间项的两倍，所以整段数列的平均值就是中间项。本题每周生产7天，日产量每天增加200件，因此周产量等于该周第4天的产量乘以7。第一周与第三周的中间项分别是第4天和第18天，产量相差14×200＝2800件。第三周总产量是第一周的2倍，所以第4天产量为2800件，首日产量为2200件。再增加39次恰好达到1万件，故首次达到目标的是第40天，选D。","references":[],"evidence":"第三周第四天的产量（即第18天）","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2023 地市级 行测#67":{"paper":"国考 2023 地市级 行测","n":67,"mod":"数量关系","src":["64bc3a15d27a04e94940.pdf",12],"asrc":["f3ab652d8e31c5bbdabc.pdf",20],"card":"db3c173891b9e15d89ecaa7e","links":[{"id":"k-4295561e641ea3cf","role":"解题依据","why":"每周的七项产量构成一段等差数列，可用该周第四天的产量计算周总产量。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-4295561e641ea3cf":[["国考 2023 地市级 行测#67"]]}};
